//! `os.lazy.net.nic.v1` client: the NIC driver's control interface and the
//! client's side of its frame rings (`idl/net.midl`,
//! `docs/networking-plan.md` section 5).
//!
//! The stubs and the [`Client`] are generated by `midlc`. Frames never cross
//! the wire: the client creates one shared buffer holding both rings
//! ([`attach`]), hands it
//! to the driver with a notify endpoint, and then moves frames through the
//! rings, waking the driver with `Kick` and being woken by `Notify`.

use alloc::format;
use alloc::string::String;
use alloc::vec;
use alloc::vec::Vec;

use framering::{ring_bytes, valid_slots, Consumer, Producer, Ring};
use libmessenger::client::{CallError, Connection, Errno};
use libmessenger::{flags, Buffer, Header, Object, Parcel, VERSION};

use super::client::{call_error, Native};
use super::{create_pair, registry, Endpoint, Error, Result};
use crate::sys;

type CallResult<T> = core::result::Result<T, CallError>;

/// The generated `os.lazy.net.nic.v1` stubs.
pub use messenger_generated::os_lazy_net_nic_v1 as wire;

/// The registry namespace of the cards: a driver serves its card as
/// `os.lazy.net.nic/<ifname>` ([`service_name`]). There is no bare name.
pub const NAME_PREFIX: &str = "os.lazy.net.nic";

/// The registered name of the card called `ifname` (`os.lazy.net.nic/eth0`).
pub fn service_name(ifname: &str) -> String {
    format!("{NAME_PREFIX}/{ifname}")
}

/// The interface name inside a registered NIC service name, if `name` is one.
pub fn ifname_of(name: &str) -> Option<&str> {
    name.strip_prefix(NAME_PREFIX)?
        .strip_prefix('/')
        .filter(|ifname| devmatch::valid_ifname(ifname))
}

/// A NIC service that is registered right now.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Present {
    pub ifname: String,
    /// The driver's task slot (the kernel-stamped sender of its messages).
    pub driver: u64,
    /// The identity the kernel holds for that task (`List` reports it; the
    /// registry only lets a driver identity hold the name, and `netd` checks
    /// again before it trusts the card).
    pub owner_uid: u64,
    pub owner_label: u64,
    pub owner_session: u64,
}

impl Present {
    /// Whether the owner is an identity that may serve a NIC
    /// (`netpolicy::may_register_nic_name`).
    pub fn owner_is_driver(&self) -> bool {
        match (
            u32::try_from(self.owner_uid),
            u32::try_from(self.owner_label),
        ) {
            (Ok(uid), Ok(label)) => {
                netpolicy::may_register_nic_name(uid, label, self.owner_session)
            }
            _ => false,
        }
    }
}

/// Every card a driver serves at this moment, in name order.
pub fn present() -> Result<Vec<Present>> {
    let mut cards: Vec<Present> = registry::list()?
        .into_iter()
        .filter_map(|entry| {
            Some(Present {
                ifname: String::from(ifname_of(&entry.name)?),
                driver: entry.owner_slot,
                owner_uid: entry.owner_uid,
                owner_label: entry.owner_label,
                owner_session: entry.owner_session,
            })
        })
        .collect();
    cards.sort_by(|a, b| a.ifname.cmp(&b.ifname));
    Ok(cards)
}

/// The interface id every NIC parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// Card description and counters.
pub use wire::{NicInfo as Info, NicStats as Stats};

/// A parcel of `method` carrying an encoded `body`, plus the objects the
/// method carries (the server's reply carries none).
pub fn parcel(method: u32, body: Vec<u8>, objects: Vec<Object>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        objects,
    }
}

/// A one-way event parcel (`Notify`, which the driver sends).
pub fn event(method: u32, body: Vec<u8>) -> Parcel {
    let mut parcel = parcel(method, body, Vec::new());
    parcel.header.flags = flags::ONE_WAY;
    parcel
}

/// A blocking client of the NIC driver, generated by `midlc`.
pub type Client = wire::Client<Native>;

/// Resolve the card `ifname`, once: the connection is to the registry name
/// `os.lazy.net.nic/<ifname>`, resolved on first use and again after a driver
/// restart. Dropping the client releases the handle it opened (the name was
/// resolved, not created, so the driver and its other clients keep theirs).
pub fn connect(ifname: &str) -> CallResult<Client> {
    let client = named(ifname)?;
    client
        .connection()
        .try_connect()
        .map_err(CallError::Transport)?;
    Ok(client)
}

/// [`connect`] for a program that may start before the driver: waits the
/// runtime's connect bound ([`super::client::CONNECT_BOUND`]).
pub fn connect_waiting(ifname: &str) -> CallResult<Client> {
    let client = named(ifname)?;
    client
        .connection()
        .connect()
        .map_err(CallError::Transport)?;
    Ok(client)
}

fn named(ifname: &str) -> CallResult<Client> {
    if !devmatch::valid_ifname(ifname) {
        return Err(CallError::Transport(Errno::INVAL));
    }
    Ok(Client::from_connection(Connection::named(
        Native,
        service_name(ifname),
    )))
}

/// Create both rings in one shared buffer and a fresh notify endpoint, and
/// attach them. The driver keeps the other side of the endpoint; the client
/// waits on its own with [`Attachment::wait`].
pub fn attach(client: &Client, slots: u32) -> CallResult<Attachment> {
    let (mine, theirs) = create_pair().map_err(call_error)?;
    let result = attach_inner(client, slots, theirs.handle(), Some(mine));
    if result.is_err() {
        // The driver never took the far end, or closed its copy.
        let _ = mine.close();
        let _ = theirs.close();
    }
    result
}

/// Create both rings and attach them, telling the driver to post `Notify`
/// into `notify`, an endpoint this task holds and **transfers** (it is gone
/// from this task's table on success). A service that already waits on one
/// endpoint passes a handle to that same endpoint, so notices and requests
/// arrive in one `recv` (`netd`). The attachment then has no notify endpoint
/// of its own.
pub fn attach_notifying(client: &Client, slots: u32, notify: Endpoint) -> CallResult<Attachment> {
    attach_inner(client, slots, notify.handle(), None)
}

fn attach_inner(
    client: &Client,
    slots: u32,
    transfer: u64,
    mine: Option<Endpoint>,
) -> CallResult<Attachment> {
    if !valid_slots(slots) {
        return Err(CallError::Transport(Errno::INVAL));
    }
    let one = ring_bytes(slots);
    // `net.midl` declares the buffer as `Ring<Rx, Tx>`: the generated
    // layout places them back to back and sizes the whole buffer.
    let layout = wire::attach_ring_rings(one as u64).ok_or(CallError::Transport(Errno::INVAL))?;
    let len = layout.total as usize;
    let (buffer, va, _) = sys::buffer_create(len as u64)
        .map_err(|code| CallError::Transport(Errno::from_syscall(-code)))?;
    let base = va as *mut u8;
    // SAFETY: the kernel mapped `len` zeroed bytes at `va`; each ring is
    // `one` bytes at an offset the layout keeps inside `len`, and the
    // mapping lives until `Attachment::close`.
    let (rx, tx) = unsafe {
        let rx = Ring::create(base.add(layout.rx as usize), one, slots);
        let tx = Ring::create(base.add(layout.tx as usize), one, slots);
        (rx, tx)
    };
    let (Ok(rx), Ok(tx)) = (rx, tx) else {
        let _ = sys::buffer_close(buffer);
        return Err(CallError::Transport(Errno::INVAL));
    };
    match client.attach_ring(slots, Buffer::whole(buffer, len as u64), transfer) {
        Ok(ring) => Ok(Attachment {
            ring,
            slots,
            buffer,
            base,
            notify: mine,
            rx: rx.consumer(),
            tx: tx.producer(),
            buf: vec![0; 256],
        }),
        Err(error) => {
            let _ = sys::buffer_close(buffer);
            Err(error)
        }
    }
}

/// What [`Attachment::split`] leaves: the driver-side ring id and the
/// resources to release once nothing reads or writes the rings any more.
pub struct Shared {
    pub ring: u32,
    buffer: u64,
    notify: Option<Endpoint>,
}

impl Shared {
    /// Unmap the shared buffer and close the notify endpoint. The ring
    /// endpoints must be gone first: they point into the buffer.
    pub fn close(self) {
        let _ = sys::buffer_close(self.buffer);
        if let Some(notify) = self.notify {
            let _ = notify.close();
        }
    }
}

/// A client's attachment: its ends of the two rings and its notify endpoint.
pub struct Attachment {
    pub ring: u32,
    pub slots: u32,
    buffer: u64,
    /// Start of the shared buffer: the receive ring, then the transmit ring.
    base: *mut u8,
    /// This client's own notify endpoint; `None` when it handed the driver an
    /// endpoint it waits on elsewhere (see [`Client::attach_notifying`]).
    notify: Option<Endpoint>,
    /// Frames from the driver: this client consumes.
    pub rx: Consumer,
    /// Frames to the driver: this client produces.
    pub tx: Producer,
    buf: Vec<u8>,
}

impl Attachment {
    /// Wait for a `Notify` until the absolute tick `deadline`. `Ok(Some(events))`
    /// carries the `NotifyBit` bitmap, `Ok(None)` a timeout. A message that is
    /// not a well-formed `Notify` is ignored, as a hostile sender could send one.
    pub fn wait(&mut self, deadline: u64) -> Result<Option<u32>> {
        let Some(notify) = self.notify else {
            return Err(Error::Errno(-super::errno::EINVAL));
        };
        match notify.recv_with(&mut self.buf, Some(deadline)) {
            Ok(message) => {
                if message.interface_id() == INTERFACE && message.method() == wire::METHOD_NOTIFY {
                    if let Ok(args) = wire::decode_notify_args(&message.parcel.body) {
                        return Ok(Some(args.events));
                    }
                }
                Ok(Some(0))
            }
            Err(Error::Errno(code)) if code == -super::errno::ETIMEDOUT => Ok(None),
            Err(error) => Err(error),
        }
    }

    /// Whether the notify endpoint is still connected (the driver holds the
    /// other side); `false` once the driver dropped the attachment.
    pub fn is_live(&mut self) -> bool {
        let Some(notify) = self.notify else {
            return true;
        };
        !matches!(
            notify.poll_recv_with(&mut self.buf), Err(Error::Errno(code)) if code == -super::errno::EPIPE)
    }

    /// Hostile-client simulation for the probe: make the transmit ring's
    /// producer index claim far more frames than the ring holds, which the
    /// driver must answer by dropping this client (and nothing worse).
    pub fn corrupt_transmit_ring(&mut self) {
        let head = ring_bytes(self.slots) + framering::off::HEAD;
        // SAFETY: the transmit ring lies inside the shared buffer this
        // attachment owns; the driver tolerates the peer writing any word.
        unsafe { core::ptr::write_volatile(self.base.add(head) as *mut u32, 0x7FFF_0000) };
    }

    /// Split into the two ring endpoints and what must be released when the
    /// attachment ends: for a consumer that owns the rings itself (a stack
    /// device) rather than driving them through this wrapper.
    pub fn split(self) -> (Consumer, Producer, Shared) {
        let shared = Shared {
            ring: self.ring,
            buffer: self.buffer,
            notify: self.notify,
        };
        (self.rx, self.tx, shared)
    }

    /// Release the shared buffer and the notify endpoint. Call
    /// [`Client::detach`] first to release the driver's side.
    pub fn close(self) {
        let _ = sys::buffer_close(self.buffer);
        if let Some(notify) = self.notify {
            let _ = notify.close();
        }
    }
}
